};
static std::shared_ptr<Pack> openPack(NSDictionary *files){auto pack=std::make_shared<Pack>();for(NSString *name in @[@"model",@"index",@"cards",@"prices"])verifyPart(files[name]);require([files[@"model"][@"sha256"] isEqual:@"98c98a68aefaf1d923ded91b71ee78a60d1eefdbb9b2202a86a01fdbe0225a4e"],"Incorrect compact model version");pack->key=jsonString(files);pack->model=TfLiteModelCreateFromFile([files[@"model"][@"path"] UTF8String]);require(pack->model,"Invalid encoder model");TfLiteInterpreterOptions *options=TfLiteInterpreterOptionsCreate();TfLiteInterpreterOptionsSetNumThreads(options,2);pack->interpreter=TfLiteInterpreterCreate(pack->model,options);TfLiteInterpreterOptionsDelete(options);require(pack->interpreter&&TfLiteInterpreterAllocateTensors(pack->interpreter)==kTfLiteOk,"Encoder setup failed");
 const TfLiteTensor *in=TfLiteInterpreterGetInputTensor(pack->interpreter,0),*out=TfLiteInterpreterGetOutputTensor(pack->interpreter,0);require(TfLiteInterpreterGetInputTensorCount(pack->interpreter)==1&&TfLiteInterpreterGetOutputTensorCount(pack->interpreter)==1&&TfLiteTensorType(in)==kTfLiteFloat32&&TfLiteTensorNumDims(in)==4&&TfLiteTensorDim(in,0)==1&&TfLiteTensorDim(in,1)==224&&TfLiteTensorDim(in,2)==224&&TfLiteTensorDim(in,3)==3&&TfLiteTensorType(out)==kTfLiteFloat32&&TfLiteTensorNumDims(out)==2&&TfLiteTensorDim(out,0)==1&&TfLiteTensorDim(out,1)==256,"Incompatible compact model tensors");
