 require(sqlite3_open_v2([files[@"cards"][@"path"] UTF8String],&pack->cards,SQLITE_OPEN_READONLY,nullptr)==SQLITE_OK&&sqlite3_open_v2([files[@"prices"][@"path"] UTF8String],&pack->prices,SQLITE_OPEN_READONLY,nullptr)==SQLITE_OK,"Invalid compact metadata");sqlite3_stmt *stmt=nullptr;require(sqlite3_prepare_v2(pack->cards,"SELECT count(*) FROM cards",-1,&stmt,nullptr)==SQLITE_OK,"Invalid metadata schema");int count=0;if(sqlite3_step(stmt)==SQLITE_ROW)count=sqlite3_column_int(stmt,0);sqlite3_finalize(stmt);require(count>=pack->index->size()&&count<=100000,"Metadata/index count mismatch");return pack;
