@interface TCGReferenceFetch:NSObject<NSURLSessionDataDelegate>
@property(nonatomic,strong) NSMutableData *data;
@property(nonatomic,strong) NSError *error;
@property(nonatomic,strong) NSHTTPURLResponse *response;
@property(nonatomic,strong) dispatch_semaphore_t done;
@end
@implementation TCGReferenceFetch
- (void)URLSession:(NSURLSession*)session task:(NSURLSessionTask*)task willPerformHTTPRedirection:(NSHTTPURLResponse*)response newRequest:(NSURLRequest*)request completionHandler:(void(^)(NSURLRequest*))completion {completion(nil);}
- (void)URLSession:(NSURLSession*)session dataTask:(NSURLSessionDataTask*)task didReceiveResponse:(NSURLResponse*)response completionHandler:(void(^)(NSURLSessionResponseDisposition))completion {
 self.response=(NSHTTPURLResponse*)response;completion(self.response.statusCode==200&&response.expectedContentLength<=4000000?NSURLSessionResponseAllow:NSURLSessionResponseCancel);
}
